    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "We included studies of humans with laboratory-con fi rmed SARS-CoV-2 infection across all healthcare settings (i.e. hospital, community, long-term care) and age groups (paediatric and adult patients). ... We included randomized controlled trials, cohort studies and case series with more than 10 patients, but excluded reviews, editorials, letters and case studies.",
      "reason": "The manuscript specifies the population (humans with laboratory-confirmed SARS-CoV-2), settings (hospital, community, long-term care), age groups (paediatric and adult), and eligible study designs (randomized controlled trials, cohort studies, case series with >10 patients)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "We performed a systematic search of MEDLINE, OVID Epub and EMBASE databases for published literature in the English language from January 1, 2019 to April 16, 2020",
      "reason": "The manuscript specifies language (English) and publication date range (January 1, 2019 to April 16, 2020). However, it does not explicitly state the eligibility criteria regarding publication status (e.g., whether preprints were included or excluded)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; the exclusion criteria provided in the text and flow diagram relate to the availability of data on bacterial infection generally, not a distinction between measurement and reporting of specific outcomes."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Seven studies exclusively reported secondary bacterial infections, the remaining 17 studies were categorized as reporting bacterial co-infection. ... When strati fi ed by patient population (an estimate of COVID-19 illness severity), bacterial infection ranged from 5.9% (95%CI 3.8 e 8.0%) in all hospitalized patients to 8.1% in critically ill patients (95%CI 2.3 e 13.8) (Fig. 3).",
      "reason": "The manuscript specifies how studies were grouped for synthesis: by infection type (co-infection vs. secondary infection) and by patient population/severity (all hospitalized vs. critically ill)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "A rapid review was selected as the ideal methodology to synthesize knowledge in a timely fashion for this emergent issue, so that learnings could impact clinical care during the ongoing pandemic. ... We included randomized controlled trials, cohort studies and case series with more than 10 patients, but excluded reviews, editorials, letters and case studies.",
      "reason": "The authors provide a rationale for the rapid review methodology (timely synthesis for an emergent issue) and for the restriction on study size (case series with more than 10 patients)."
    }
  ],
  "confidence": 95
}

